package ai.decisionos.aside;
import android.app.*;import android.os.*;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;
/** Sequential SSO probes share Android's app WebView cookie profile. No credential extraction. */
final class SchoolSignIn {
 final GoalChatUi c;final GoalAgentActivity a;final Handler handler=new Handler(Looper.getMainLooper());
 final String[] ids={"portal","blackboard","mail"};final String[] urls={"https://portal.unist.ac.kr/","https://blackboard.unist.ac.kr/","https://sso-token.unist.ac.kr/email"};
 int index=0,generation=0;boolean closed=false;String followedSso="",accountHint="";boolean portalButtonClicked=false,courseRequested=false;WebView web;TextView title,detail,origin;Button next;Dialog dialog;long started;
 SchoolSignIn(GoalChatUi chat){c=chat;a=chat.a;}
 static boolean allowed(String url){try{Uri u=Uri.parse(url);String h=u.getHost();return "https".equals(u.getScheme())&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&h!=null&&(h.equals("unist.ac.kr")||h.endsWith(".unist.ac.kr")||h.equals("outlook.office.com")||h.equals("outlook.office365.com")||h.equals("outlook.cloud.microsoft")||h.equals("login.microsoftonline.com")||h.equals("login.live.com"));}catch(Exception e){return false;}}
 static boolean interactive(String id){return "portal".equals(id);}
 boolean revealLogin(){if(index>=ids.length||!interactive(ids[index]))return false;web.setVisibility(View.VISIBLE);return true;}
 static boolean verified(String id,String url,boolean input,boolean evidence){if(input||!evidence)return false;String h=Uri.parse(url).getHost();if("mail".equals(id))return url.startsWith("https://")&&("outlook.office.com".equals(h)||"outlook.office365.com".equals(h)||"outlook.cloud.microsoft".equals(h));return CampusFlowStore.verifiedConnection(id,url,false,evidence);}
 void show(){LinearLayout root=c.box(NubiCompanionUi.WHITE,18);title=a.txt("학교생활 준비, 세 가지만 연결할게",23,NubiCompanionUi.INK,true);root.addView(title);detail=a.txt("포털에서 한 번 로그인하면 같은 앱의 세션을 보관할게. Blackboard와 메일은 별도 로그인창 없이 자동 연결을 확인해.",15,NubiCompanionUi.MUTED,false);root.addView(detail,Ui.match(a,-2,12));origin=a.txt("UNIST · 포털 → Blackboard → Outlook",12,NubiCompanionUi.MUTED,false);root.addView(origin,Ui.match(a,-2,8));
 web=new WebView(a);WebSessionPolicy.attach(web);web.setVisibility(View.INVISIBLE);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));
 next=a.button("다음 · 학교 계정 연결",true);root.addView(next,Ui.match(a,54,16));next.setOnClickListener(v->{if(index>=3){dialog.dismiss();SchoolChatUi.open(c,"");return;}if(web.getUrl()==null)load();else check(generation,false);});
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return r.isForMainFrame()&&!allowed(r.getUrl().toString());}public void onPageFinished(WebView v,String url){CookieManager.getInstance().flush();if(closed)return;origin.setText(Uri.parse(url).getHost());handler.postDelayed(()->check(generation,false),800);}});
 Button vaultButton=a.button("학교 계정 보관·저장 계정 로그인",false);root.addView(vaultButton,Ui.match(a,48,8));vaultButton.setOnClickListener(v->{dialog.dismiss();a.startActivity(new android.content.Intent(a,CredentialVaultActivity.class));});
 Button later=a.button("나중에 연결할게",false);root.addView(later,Ui.match(a,48,8));dialog=new Dialog(a);dialog.setContentView(root,new ViewGroup.LayoutParams(-1,-1));later.setOnClickListener(v->dialog.dismiss());dialog.setOnDismissListener(d->{closed=true;generation++;handler.removeCallbacksAndMessages(null);web.stopLoading();web.destroy();CookieManager.getInstance().flush();if(!a.isFinishing())c.render();});dialog.show();dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(NubiCompanionUi.WHITE));dialog.getWindow().setLayout(-1,-1);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
 }
 void load(){if(index>=3){finish();return;}if(index>0){try(CampusFlowStore store=new CampusFlowStore(a)){if(!"verified".equals(store.get("connection-portal").optString("state"))){record(false,urls[index]);index++;load();return;}}}generation++;followedSso="";portalButtonClicked=false;courseRequested=false;next.setVisibility(View.GONE);started=System.currentTimeMillis();web.setVisibility(View.INVISIBLE);title.setText((index+1)+" / 3 · "+CampusWorkflows.service(ids[index])[1]);detail.setText(index>0?"포털 세션으로 학교 서비스를 자동 연결하고 있어. 별도 로그인창은 띄우지 않을게.":"보관한 학교 로그인 세션으로 연결을 확인하고 있어.");next.setText("연결 확인 중");int token=generation;web.loadUrl(urls[index]);handler.postDelayed(()->{if(!closed&&token==generation){if(!interactive(ids[index])){record(false,web.getUrl());index++;load();return;}revealLogin();detail.setText("연결이 늦어지고 있어. 공식 화면에서 로그인을 완료해 줘.");next.setVisibility(View.GONE);}},45000);}
 void check(int token,boolean manual){if(closed||token!=generation||index>=3)return;
 if(manual){probe(token,true);return;}probe(token,false);
 }
 void probe(int token,boolean skip){web.evaluateJavascript("(()=>{const visible=e=>!!e.getClientRects().length;return JSON.stringify({url:location.href,accountInput:(document.querySelector('input[type=email]')||{}).value||'',accountIdentity:((document.querySelector('[data-email]')||{}).dataset||{}).email||([...document.querySelectorAll('[id^=mectrl_]')].filter(e=>/email|secondary|username/i.test(e.id)).map(e=>e.textContent||'').join(' ').match(/[A-Z0-9._%+-]+@unist[.]ac[.]kr/i)||[])[0]||[...document.querySelectorAll('[aria-label],[title]')].map(e=>e.getAttribute('aria-label')||e.title||'').join(' ').match(/[A-Z0-9._%+-]+@unist[.]ac[.]kr/i)?.[0]||'',portalButton:location.hostname==='blackboard.unist.ac.kr'&&!!document.querySelector('#unist-portal-login'),input:[...document.querySelectorAll('input:not([type=hidden])')].some(e=>visible(e)&&(/password|email|tel/.test(e.type)||/user|login|otp|code/i.test(e.name||e.id))),sso:[...document.querySelectorAll('a[href]')].filter(visible).filter(e=>/UNIST.*(로그인|login)|(로그인|login).*UNIST|institution.*login|login.*institution/i.test(e.innerText||'')).map(e=>e.href)[0]||'',evidence:[...document.querySelectorAll('a,button,[role=button]')].some(e=>visible(e)&&/^(로그아웃|Sign out|Log out|Logout|My profile|이 계정에서 로그아웃|새 메일 작성|New mail)$/i.test((e.innerText||e.getAttribute('aria-label')||'').trim()))||(location.hostname==='blackboard.unist.ac.kr'&&!!document.querySelector('a[href*=\"/ultra/courses/\"]'))})})()",raw->{if(closed||token!=generation)return;try{JSONObject j=new JSONObject(new JSONArray("["+raw+"]").getString(0));String hint=(j.optString("accountInput").isEmpty()?j.optString("accountIdentity"):j.optString("accountInput")).trim().toLowerCase(java.util.Locale.ROOT);if(hint.matches("[a-z0-9._%+-]+@unist[.]ac[.]kr"))accountHint=hint;boolean ok=verified(ids[index],j.optString("url"),j.optBoolean("input"),j.optBoolean("evidence"));if(ok){record(ok,j.optString("url"));index++;load();return;}if(index>0){if(index==1&&!j.optBoolean("input")&&j.optString("url").startsWith("https://blackboard.unist.ac.kr/ultra/institution-page")&&!courseRequested){courseRequested=true;started=System.currentTimeMillis();web.loadUrl("https://blackboard.unist.ac.kr/ultra/course");return;}if(index==1&&j.optBoolean("portalButton")&&!portalButtonClicked){portalButtonClicked=true;started=System.currentTimeMillis();web.evaluateJavascript("(()=>{if(location.hostname==='blackboard.unist.ac.kr'){const b=document.getElementById('unist-portal-login');if(b)b.click();}})()",v->handler.postDelayed(()->check(token,false),1500));return;}String link=j.optString("sso");if(!link.isEmpty()&&!link.equals(followedSso)&&allowed(link)&&Uri.parse(link).getHost().endsWith(".unist.ac.kr")){followedSso=link;web.loadUrl(link);return;}if(j.optBoolean("input")||System.currentTimeMillis()-started>30000){record(false,j.optString("url"));index++;load();return;}}if(j.optBoolean("input")||System.currentTimeMillis()-started>30000){revealLogin();detail.setText("여기서만 직접 입력해 줘. 로그인되면 다음 연결을 자동으로 확인할게.");next.setVisibility(View.GONE);}handler.postDelayed(()->check(token,false),2000);}catch(Exception e){if(index>0){record(false,web.getUrl());index++;load();return;}revealLogin();detail.setText("공식 화면에서 연결을 확인해 줘.");}});}
 void record(boolean ok,String url){if(ok&&!accountHint.isEmpty())try{JSONObject receipt=new JSONObject();receipt.put("kind","webview_session_reference");receipt.put("profile","Default");receipt.put("verifiedAt",System.currentTimeMillis());receipt.put("service",ids[index]);SchoolAccountKeys.save(a,accountHint,ids[index],receipt);}catch(Exception e){a.toast("계정별 연결 기록 저장 실패 · 로그인 세션은 브라우저에서 유지돼.");}try(CampusFlowStore s=new CampusFlowStore(a)){JSONObject r=new JSONObject();GoalStore.put(r,"id","connection-"+ids[index]);GoalStore.put(r,"service",ids[index]);GoalStore.put(r,"state",ok?"verified":"needs_verification");GoalStore.put(r,"reason",ok?"공식 서비스 화면의 로그인 증거 확인":index==0?"포털 재인증 또는 화면 확인 필요":"포털 SSO 자동 연결 미확인. 별도 자격증명을 입력하지 않았으며 연결 성공으로 간주하지 않음");GoalStore.put(r,"url",url==null?"":Uri.parse(url).buildUpon().clearQuery().fragment(null).build().toString());GoalStore.put(r,"mode",index>0?"portal_sso":"interactive_or_session");s.save("connections",r);}CookieManager.getInstance().flush();if(ok&&index==0){CampusNoticeMonitor.schedule(a);CampusNoticeMonitor.scheduleNow(a);}if(ok&&index==1){BlackboardNoticeMonitor.schedule(a,false);BlackboardNoticeMonitor.schedule(a,true);}}
 void finish(){generation++;web.setVisibility(View.INVISIBLE);title.setText("연결 결과를 함께 볼까?");StringBuilder summary=new StringBuilder();try(CampusFlowStore s=new CampusFlowStore(a)){for(String id:ids)summary.append(s.get("connection-"+id).optString("state").equals("verified")?"✓ ":"○ ").append(CampusWorkflows.service(id)[1]).append(s.get("connection-"+id).optString("state").equals("verified")?" · 연결 확인\n":id.equals("blackboard")?" · 포털 세션 자동 연결 미확인\n":" · 추가 확인 필요\n");}detail.setText(summary+"\n이제 필요한 일을 채팅에 말해 줘.");next.setVisibility(View.VISIBLE);next.setText("똑똑이와 이야기하기");}
}
